function gerarSenha() {
  const maiusculas = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const minusculas = 'abcdefghijklmnopqrstuvwxyz';
  const numeros = '0123456789';
  const especiais = '@#$%';
  const todosCaracteres = maiusculas + minusculas + numeros + especiais;

  // Gera um tamanho aleatório entre 8 e 12
  const tamanho = Math.floor(Math.random() * 5) + 8;

  // Garante pelo menos um de cada tipo
  let senha = [
    maiusculas[Math.floor(Math.random() * maiusculas.length)],
    minusculas[Math.floor(Math.random() * minusculas.length)],
    numeros[Math.floor(Math.random() * numeros.length)],
    especiais[Math.floor(Math.random() * especiais.length)]
  ];

  // Completa o restante da senha
  for (let i = senha.length; i < tamanho; i++) {
    senha.push(todosCaracteres[Math.floor(Math.random() * todosCaracteres.length)]);
  }

  // Embaralha a senha
  for (let i = senha.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [senha[i], senha[j]] = [senha[j], senha[i]];
  }

  return senha.join('');
}

function gerarTelefone() {
    const primeiroDigito = Math.floor(Math.random() * 9) + 1;

    const restante = Array(10)
        .fill()
        .map(() => Math.floor(Math.random() * 10));

    return [primeiroDigito, ...restante].join('');
}

